from pathlib import Path
import ast, hashlib, shutil, sys, re

TARGET = Path('wa_backend/api/dispatch.py')
BACKUP_DIR = Path('.patch_backups/DISPATCH_RUNTIME_EMERGENCY_HARDENING')
BACKUP_FILE = BACKUP_DIR / 'dispatch.py.before_runtime_emergency_hardening'
EXPECTED_SHA256 = '5e06eb1a9b1e6c395ec33eb83cb15c2e1c6c645f05edb12b24d6937145a3b4f8'

def fail(msg):
    raise SystemExit(f'PATCH_ABORTED: {msg}')

def replace_once(text, old, new, label):
    count = text.count(old)
    if count == 0 and new in text:
        return text
    if count != 1:
        fail(f'{label}: expected one anchor, found {count}')
    return text.replace(old, new, 1)

if not TARGET.exists(): fail(f'target not found: {TARGET}')
text = TARGET.read_text(encoding='utf-8')
current_sha = hashlib.sha256(text.encode('utf-8')).hexdigest()
already = (
    '_dispatch_load_bound_session' not in text
    and '_dispatch_absolute_inventory_targets' not in text
    and 'item.productId' not in text
    and 'func.hashtext(f"shortage:{shop_id}:{product_id}")' in text
    and 'phone_number=s_phone or None' in text
)
if already:
    print('DISPATCH_RUNTIME_EMERGENCY_HARDENING_ALREADY_OK')
    sys.exit(0)
if current_sha != EXPECTED_SHA256:
    fail(f'unexpected dispatch.py SHA256: {current_sha}. Expected exact post-stage3 file.')

